import * as React from "react"
import { Link } from "gatsby"
import { styled } from "styled-components"

export function Article({
  link,
  post,
}: {
  link?: boolean
  post: {
    excerpt: string
    html: string
    fields: { slug: string }
    frontmatter: {
      title?: string
      date: string
      description: string
    }
  }
}) {
  return (
    <ArticleContainer itemScope itemType="http://schema.org/Article">
      <header>
        {post.frontmatter.title && <h1>{post.frontmatter.title}</h1>}
        {link ? (
          <DateLink to={post.fields.slug}>
            <Date itemProp="headline">{post.frontmatter.date}</Date>
          </DateLink>
        ) : (
          <Date itemProp="headline">{post.frontmatter.date}</Date>
        )}
      </header>
      <ArticleBody
        dangerouslySetInnerHTML={{ __html: post.html }}
        itemProp="articleBody"
      />
    </ArticleContainer>
  )
}

const ArticleContainer = styled.article`
  margin: 0 0 4em 0;
`

const ArticleBody = styled.section`
  font-family: times, serif;
  font-size: 20px;
`

const DateLink = styled(Link)`
  color: var(--color-fg);
  &:visited {
    color: var(--color-fg);
  }
`

const Date = styled.h1`
  font-size: 1em;
  font-weight: normal;
`
